def setup(mp,expanded=False):
 p=Panel('recent','dyad',mp,classes='C');needed={'Gap','Distance','Distributed','Shared','LogSize','LogBreadth','LogProductivity'};needed|={'Applicability','Access'}if expanded else set();raw,z,sc=constructs(p,needed);terms=['Gap','Distance','Distributed','Shared']+(['Applicability','Access']if expanded else[]);extras=['LogBreadth','LogProductivity'];names=[k+'_'+s for k in terms for s in ['Destination','Home']]+[k+'_Destination'for k in extras];ref=load(F/'results/dyad/recent'/mp/'architecture/architecture_estimable__signed.json');assert expanded or names==ref['meta']['names'];oldsc=load(F/'results/dyad/recent'/mp/'architecture/scaling.json');assert all(abs(sc[k]['sd']-oldsc[k]['sd'])<1e-12 for k in oldsc);return p,z,sc,terms,extras,names
def paths(mp,only_k=None,only_family=None,accelerated=False):
 p,z,sc,terms,extras,names=setup(mp);base=F/'verification/recent_dyad'/mp;out=base/('accelerated_paths'if accelerated else'paths');out.mkdir(parents=True,exist_ok=True);e,v,yn=first_events(p);wh=p.hist[:,p.js]/p.hist[:,p.js].sum(1,keepdims=True).clip(1);save(out/'scaling.json',sc)
 def job(task):
  family,k=task;dest=out/family/str(p.paths[k]);dest.mkdir(parents=True,exist_ok=True)
  if(dest/'COMPLETE').exists():return
  other=base/('paths'if accelerated else'accelerated_paths')/family/str(p.paths[k])
  if(other/'COMPLETE').exists():return
  sel=p.fc!=k if family=='risk'else np.ones(p.J,bool);mask0=p.mask[:,sel];rows=np.flatnonzero(mask0.any(1));mask=mask0[rows];A=p.A[sel].copy();ha=p.ha[rows].copy()
  if family=='input':A[p.fc==k]=0;ha-=wh[rows][:,p.fc==k]@p.A[p.fc==k]
  zz={nm:z[nm][rows][:,sel]for nm in terms+extras};il=np.full(p.I,-1,int);il[rows]=np.arange(len(rows));jl=np.full(p.J,-1,int);jl[np.flatnonzero(sel)]=np.arange(sel.sum());em=e.i.isin(rows)&e.j0.isin(np.flatnonzero(sel));ev=e[em];vals=v[em.to_numpy()];data=SparseBatch(il[ev.i],jl[ev.j0],ev.mo-786,vals,yn,len(rows),int(sel.sum()),p.T,mask)
  def fx(a,b):return np.stack([zz[nm][a:b,:,None]*(A[None,:,:]if src=='Destination'else ha[a:b,None,:])for nm in terms for src in ['Destination','Home']]+[zz[nm][a:b,:,None]*A[None,:,:]for nm in extras],axis=3)
  def ctrl(a,b):return np.stack([zz[nm][a:b]for nm in terms],axis=2)
  d=ReportingDesign(mask,p.fc[sel],p.home[rows],names,fx,ctrl,True,1024);d.fit_many(data,dest,'',cap_only=True);save(dest/'definition.json',{'family':family,'omitted_path':str(p.paths[k]),'fixed_full_population_scales':True,'exact_FE_refit':True,'covariance_scope':'exact capability-path covariance only; primary five schemes preserved','Home':'unchanged'if family=='risk'else'original omitted input contribution removed, no renormalization','both_exposures_changed':family=='input','zero_inclusive':True,'label':'targeted post-discovery robustness','outcomes':yn});(dest/'COMPLETE').write_text('All four components attempted; rank failures retained.');log('VERIFICATION PATH',mp,family,p.paths[k]);del d,data,zz;gc.collect()
 tasks=[(family,k)for family in ['risk','input']for k in range(len(p.paths))if(only_k is None or k==only_k)and(only_family is None or family==only_family)]
 with concurrent.futures.ThreadPoolExecutor(max_workers=1 if only_k is not None else 16)as ex:list(ex.map(job,tasks))
 p.c.close()
def validity(mp):
 p,z,sc,terms,extras,names=setup(mp);out=F/'verification/recent_dyad'/mp/'validity';out.mkdir(parents=True,exist_ok=True)
 if(out/'COMPLETE').exists():return
 f=p.firsts().merge(pd.read_parquet(p.u/'sourcing/frozen_extra_counts.parquet'),on=['g','work_id'],how='left',validate='one_to_one');missing=f.extra_specialists.isna();assert f.loc[missing,'authors_n'].eq(2).all();f[['extra_specialists','current_extra_specialists']]=f[['extra_specialists','current_extra_specialists']].fillna(0);f['S']=f.current_experts>f.current_core_experts;assert np.array_equal(f.S,f.current_extra_specialists>0);f['F']=f.extra_specialists>0;f['expanded']=f.authors_n>2;f['core_expert']=f.current_core_experts>0;f['complete']=f.authors_with_prior_records==f.authors_n;e=f.groupby(['i','j0','mo']).agg(S=('S','max'),F=('F','max'),expanded=('expanded','max'),core=('core_expert','max'),complete=('complete','all')).reset_index();assert(e.F<=e.S).all();no=~e.S;cur=2*e.S.to_numpy(float)-1;fro=2*e.F.to_numpy(float)-1;ys={'current_signed':cur,'frozen_signed':fro,'current_minus_frozen':cur-fro,'specialist':e.S.astype(float),'exact_no':(no&~e.expanded).astype(float),'expanded_no':(no&e.expanded).astype(float),'no_current_core_expert':(no&~e.core).astype(float),'with_current_core_expert':(no&e.core).astype(float),'complete_no':(no&e.complete).astype(float),'uncertain_no':(no&~e.complete).astype(float),'exact_minus_expanded':np.where(no,np.where(e.expanded,-1.,1.),0.)}
 assert np.array_equal(ys['exact_no']+ys['expanded_no'],no.astype(float));assert np.array_equal(ys['no_current_core_expert']+ys['with_current_core_expert'],no.astype(float));assert np.array_equal(ys['complete_no']+ys['uncertain_no'],no.astype(float));data=p.aggregate(e,np.column_stack(list(ys.values())),list(ys))
 def fx(a,b):return np.stack([z[nm][a:b,:,None]*(p.A[None,:,:]if src=='Destination'else p.ha[a:b,None,:])for nm in terms for src in ['Destination','Home']]+[z[nm][a:b,:,None]*p.A[None,:,:]for nm in extras],axis=3)
 def ctrl(a,b):return np.stack([z[nm][a:b]for nm in terms],axis=2)
 d=ReportingDesign(p.mask,p.fc,p.home,names,fx,ctrl,True,1024);d.fit_many(data,out,'',save_joint=True);ref=load(F/'results/dyad/recent'/mp/'architecture/architecture_estimable__signed.json');r=load(out/'current_signed.json');assert np.allclose(r['sufficient_statistics']['beta'],ref['sufficient_statistics']['beta'],rtol=1e-8,atol=1e-12);assert np.allclose(r['covariance']['capability'],ref['covariance']['capability'],rtol=1e-6,atol=1e-14);save(out/'definition.json',{'label':'targeted post-discovery outcome/construct validation','primary_signed_and_covariance_reproduced':True,'all_zero_C_candidates':True,'exact_no':'No current outside specialist and every first-month paper has exactly the entire two-person core','expanded_no':'No current outside specialist and at least one first-month paper adds authors','specialist_priority':True,'expertise_freeze_alternative_only_changes_outside_specialist_definition':True,'no_current_core_expert':'No additional specialist and no first-month paper has a core author with strictly prior-year destination experience','history_complete':'Every author on every first-month paper has prior classified publications; does not prove disambiguation','not_post_treatment_controls':True});(out/'COMPLETE').write_text('All fixed partitions estimated; benchmark identities verified.');log('VERIFICATION VALIDITY',mp)
